def gen(rng):
    D = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def groups(g, r, c):
        seen = set()
        res = []
        for i in range(r):
            for j in range(c):
                if g[i][j] != '.' and (i, j) not in seen:
                    col = g[i][j]
                    cells = [(i, j)]
                    seen.add((i, j))
                    k = 0
                    libs = False
                    while k < len(cells):
                        x, y = cells[k]
                        k += 1
                        for dx, dy in D:
                            a, b = x + dx, y + dy
                            if 0 <= a < r and 0 <= b < c:
                                if g[a][b] == '.':
                                    libs = True
                                elif g[a][b] == col and (a, b) not in seen:
                                    seen.add((a, b))
                                    cells.append((a, b))
                    res.append((cells, libs))
        return res

    def legalize(g, r, c):
        for cells, libs in groups(g, r, c):
            if not libs:
                for x, y in cells:
                    g[x][y] = '.'

    def answer(g, r, c, pr, pc):
        h = [row[:] for row in g]
        h[pr][pc] = 'B'
        tot = 0
        for cells, libs in groups(h, r, c):
            if not libs and h[cells[0][0]][cells[0][1]] == 'W':
                tot += len(cells)
        return tot

    def fmt(g, r, c, pr, pc):
        return f'{r} {c}\n{pr} {pc}\n' + '\n'.join(''.join(row) for row in g)

    def random_case(want_positive):
        for _ in range(400):
            r, c = rng.randint(1, 8), rng.randint(1, 8)
            pw = rng.choice([0.25, 0.35, 0.5])
            pb = rng.choice([0.3, 0.4, 0.5])
            g = [['W' if rng.random() < pw else ('B' if rng.random() < pb else '.') for _ in range(c)] for _ in range(r)]
            legalize(g, r, c)
            empties = [(i, j) for i in range(r) for j in range(c) if g[i][j] == '.']
            if not empties:
                i, j = rng.randrange(r), rng.randrange(c)
                g[i][j] = '.'
                empties = [(i, j)]
            if want_positive:
                rng.shuffle(empties)
                for pr, pc in empties:
                    if answer(g, r, c, pr, pc) > 0:
                        return fmt(g, r, c, pr, pc)
            else:
                pr, pc = rng.choice(empties)
                return fmt(g, r, c, pr, pc)
        return fmt([['.']], 1, 1, 0, 0)

    tests = [
        '1 1\n0 0\n.',
        '1 2\n0 1\nW.',
        '1 3\n0 2\nBW.',
        '2 2\n1 1\nBW\nW.',
        '3 3\n0 1\n...\n.W.\n...',
        '4 7\n2 5\n....BBB\n....BWB\n....B.B\n.......',
        '5 5\n2 2\n.BB..\nBWWB.\n.B.B.\n..B..\n....W',
        '3 5\n1 2\n.BBB.\nBW.WB\n.BBB.',
        '3 5\n1 2\n.BBB.\nBW.W.\n.BBB.',
        '3 3\n1 1\nWWW\nW.W\nWWW',
    ]
    for _ in range(20):
        tests.append(random_case(True))
    for _ in range(12):
        tests.append(random_case(False))

    R = C = 500
    # one huge white group whose only liberty is the move
    g = [['W'] * C for _ in range(R)]
    g[R - 1][C - 1] = '.'
    tests.append(fmt(g, R, C, R - 1, C - 1))
    # same, but a second liberty far away: nothing is captured
    g[0][0] = '.'
    tests.append(fmt(g, R, C, R - 1, C - 1))
    # serpentine white corridor sealed by black walls, single liberty at the end
    R2 = 497
    g = [['W'] * C for _ in range(R2)]
    for k in range(124):
        gap = C - 1 if k % 2 == 0 else 0
        side = gap - 1 if gap else gap + 1
        for t in range(1, 4):
            row = 4 * k + t
            for j in range(C):
                g[row][j] = 'B'
            g[row][gap] = 'W'
        mid = 4 * k + 2
        for j in range(C):
            if j != gap and j != side:
                g[mid][j] = '.'
    g[R2 - 1][C - 1] = '.'
    tests.append(fmt(g, R2, C, R2 - 1, C - 1))
    # large random board with a legal position
    g = [['W' if rng.random() < 0.3 else ('B' if rng.random() < 0.3 else '.') for _ in range(C)] for _ in range(R)]
    legalize(g, R, C)
    tests.append(fmt(g, R, C, 250, 250 if g[250][250] == '.' else 251) if False else fmt([['.' if g[i][j] == '.' or (i, j) == (250, 250) else g[i][j] for j in range(C)] for i in range(R)], R, C, 250, 250))
    return tests

